let colors = ['#e6302b', '#36ad63', '#fbd400', '#ffffff', '#f654a9', '#2B50AA'];
let ctx;
let centerX, centerY;
let shapes = [];

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	centerX = width / 2;
	centerY = height / 2;

	let cellCount = 35;
	let gridArea = width * 0.85;
	let cellSize = gridArea / cellCount;
	let d = cellSize;
	for (let j = 0; j < cellCount; j++) {
		for (let i = 0; i < cellCount; i++) {
			let x = i * cellSize + (cellSize / 2) + (width - gridArea) / 2;
			let y = j * cellSize + (cellSize / 2) + (height - gridArea) / 2;
			let dst = dist(x, y, centerX, centerY);
			let ang = map(atan2(centerY - y, centerX - x), -PI, PI, 0, 1);
			let t = map(dst, 0, sqrt(sq(width / 2) + sq(height / 2)), -0, -200) - ang * 120;
			if ((i + j) % 2 == 0) {
				shapes.push(new Shape(x, y, d, t));
			}
		}
	}
}

function draw() {
	background('#232323');
	for (let s of shapes) {
		s.run();
	}
}

function drawMoon(x, y, diameter, startOffset, endOffset, angle) {
	let radius = diameter * 0.5;
	let startOffsetMapped = map(startOffset, 0, 1, -1, 1) * radius;
	let endOffsetMapped = map(endOffset, 0, 1, -1, 1) * radius;
	push();
	translate(x, y);
	rotate(angle);
	beginShape();
	for (let angle = 0; angle < PI; angle += PI / 90) {
		vertex(radius * cos(angle), startOffsetMapped * sin(angle));
	}
	for (let angle = PI; angle < TAU; angle += PI / 90) {
		vertex(radius * cos(angle), endOffsetMapped * sin(angle));
	}
	endShape();
	pop();
}

function easeInOutCubic(x) {
	return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
}

class Shape {
	constructor(x, y, d, t) {
		this.x = x;
		this.y = y;
		this.d = d;
		this.ang0 = random(10);
		this.ang1 = this.ang0 + PI;
		this.ang = this.ang0;
		this.timer = t;
		this.timings = [];
		for (let i = 0; i < 10; i++) {
			this.timings[i] = (i * 60);
		}
		this.offset1 = 0;
		this.offset2 = 1;
		this.clr1 = random(colors);
		this.clr2 = random(colors);
	}

	show() {
		noStroke();
		fill(this.clr1);
		circle(this.x, this.y, this.d / 2);
		fill(this.clr2);
		drawMoon(this.x, this.y, this.d, this.offset1, this.offset2, this.ang);
	}

	update() {
		this.timer++;

		for (let i = 0; i < this.timings.length - 1; i++) {
			if (this.timings[i] < this.timer && this.timer < this.timings[i + 1]) {
				let nrm = norm(this.timer, this.timings[i], this.timings[i + 1] - 1);
				if (i == 0) {
					this.offset1 = lerp(0, 1, easeInOutCubic(nrm));
					this.ang = lerp(this.ang0, this.ang1, easeInOutCubic(nrm));
				} else if (i == 1) {
					this.offset2 = lerp(1, 0, easeInOutCubic(nrm));
					this.ang = lerp(this.ang1, this.ang0, easeInOutCubic(nrm));
				}
			}
		}

		if (this.timer > this.timings[2]) {
			this.timer = 0;
			this.offset1 = 0;
			this.offset2 = 1;
			this.clr2 = random(colors);
		}

		if (this.timer == this.timings[1]) {
			this.clr1 = random(colors);
		}
	}

	run() {
		this.show();
		this.update();
	}
}

